package dev.smpcristalix.pvpcombat.service;
import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.scoreboard.*;
/** Sidebar показывается только во время Combat. */
public final class ScoreboardService{private final CombatService combat;private final PearlService pearls;private PvPCombatSettings settings;public ScoreboardService(CombatService c,PearlService p,PvPCombatSettings s){combat=c;pearls=p;settings=s;}public void reload(PvPCombatSettings s){settings=s;}public void update(Player p){if(!combat.inCombat(p))return;var board=Bukkit.getScoreboardManager().getNewScoreboard();var o=board.registerNewObjective("pvpcombat",Criteria.DUMMY,ChatColor.RED+"PvPCombat");o.setDisplaySlot(DisplaySlot.SIDEBAR);long sec=(combat.remainingMillis(p)+999)/1000;o.getScore(ChatColor.WHITE+"⚔ PvP: "+ChatColor.RED+sec+" сек.").setScore(2);long cd=pearls.cooldownSeconds(p);String line=cd>0?ChatColor.WHITE+"◉ Жемчуг: "+ChatColor.YELLOW+"КД "+cd+" сек.":ChatColor.WHITE+"◉ Жемчуг: "+ChatColor.AQUA+pearls.remaining(p)+"/"+settings.pearlCharges();o.getScore(line).setScore(1);p.setScoreboard(board);}public void clear(Player p){p.setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());}}
